def cells(key,expert=False):
 d=o[key];return f"<td>{d.get('Ink_faster' if expert else 'faster',0)}</td><td>{d.get('expert_faster' if expert else 'slower',0)}</td><td>{d.get('inconclusive',0)}</td>"
rows=[('Node JS','fresh|node||prior_over_checked_js|all'),('Browser JS','fresh|browser||prior_over_checked_js|all'),('Node Wasm','fresh|node||prior_over_checked_wasm|all'),('Browser Wasm','fresh|browser||prior_over_checked_wasm|all'),('Native C resident','fresh|native|resident|prior_over_checked|all'),('Native C snapshot','fresh|native|snapshot|prior_over_checked|all')]
expert=[('Native C resident / expert Rust','fresh|native|resident|checked_over_rust_expert|all'),('Native C snapshot / expert Rust','fresh|native|snapshot|checked_over_rust_expert|all'),('Browser captured JS / expert JS','fresh|browser||ink_checked_js_over_js_expert|all'),('Browser Ink Wasm / expert Rust Wasm','fresh|browser||ink_checked_wasm_over_rust_expert_wasm|all'),('Browser GPU / expert JS','fresh|browser||js_expert_over_ink_checked_gpu|all')]
table=lambda rs,ex=False:'<table><thead><tr><th>Complete-call boundary</th><th>'+('Ink wins' if ex else 'Improvements')+'</th><th>'+('Expert wins' if ex else 'Regressions')+'</th><th>Inconclusive</th></tr></thead><tbody>'+''.join('<tr><td>'+label+'</td>'+cells(key,ex)+'</tr>' for label,key in rs)+'</tbody></table>'
s='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Ink proof batch 19 — verified results</title><style>body{font:16px system-ui,sans-serif;background:#f2f5f4;color:#17352c;margin:0;padding:34px}main{max-width:1050px;margin:auto}h1{font-size:31px;margin:0 0 8px}h2{font-size:20px;margin:22px 0 10px}.lead{font-size:18px;max-width:980px;line-height:1.5}.metrics{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin:20px 0}.metric{background:white;border:1px solid #c8d8d1;padding:15px;border-radius:9px}.metric strong{display:block;font-size:28px}.note{background:#fff5db;border:1px solid #ead69b;padding:14px;border-radius:8px;line-height:1.5}table{width:100%;border-collapse:collapse;background:white;border:1px solid #c8d8d1}th,td{text-align:left;padding:9px 12px;border-bottom:1px solid #dce6e1}td:not(:first-child),th:not(:first-child){text-align:right}th{background:#e0ede7}footer{font-size:14px;line-height:1.5;margin-top:16px}a{color:#156146}</style><main><h1>Ink proof batch 19</h1><p class="lead">Checked compile-time laws combine complementary partitions and fuse same-source mapped zip pipelines. Arbitrary pure callbacks; no new runtime checks.</p><div class="metrics"><div class="metric"><strong>13</strong>generic laws · four families</div><div class="metric"><strong>15,120</strong>timing samples</div><div class="metric"><strong>4,624</strong>complete comparisons</div><div class="metric"><strong>1,488</strong>independently verified intervals</div></div><div class="note"><strong>Broad native superiority is not established.</strong> Expert Rust wins 44/48 native cells per mode. Current GPU loses to expert JS in all 48 cells. All 36 prior/current regressions remain in the report.</div><h2>Current Ink versus fair prior Ink — 48 cells per row</h2>'''+table(rows)+'''<h2>Current Ink versus strong expert implementations</h2>'''+table(expert,True)+'''<footer>All eight current GPU recipes are newly eligible; prior GPU calls fall back to CPU. There are no same-backend prior/current GPU speedup comparisons. Mathematical correctness and target profitability are separate.<br>DB: 1,343 entries = 1,298 historical + 13 generic + 8 new static certificates + 24 old static certificates shared by both comparisons. 11,586 observations. One machine, eight preset U32 recipes; exploratory unadjusted individual intervals, correlated views.<br><a href="REPORT.md">Full proof and performance report</a> · <a href="verification.json">Final verification</a> · <a href="fresh-regressions.json">All regressions</a></footer></main></html>'''
